public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;
    int n = s.length();
    int best = 0;
    ArrayDeque<State> stack = new ArrayDeque<>();
    stack.push(new State(0, new HashSet<>(), 0));
    while (!stack.isEmpty()){
        State cur = stack.pop();
        if (cur.index == n){
            best = Math.max(best, cur.count);
            continue;
        }
        for (int len=1; len <= n - cur.index; len++){
            String sub = s.substring(cur.index, cur.index+len);
            if (!cur.seen.contains(sub)){
                HashSet<String> newSet = new HashSet<>(cur.seen);
                newSet.add(sub);
                stack.push(new State(cur.index+len, newSet, cur.count+1));
            }
        }
    }
    return best;
}

