            String sub = s.substring(index, index+len);
            if (!seen.contains(sub)){
                java.util.Set<String> newSeen = new java.util.HashSet<>(seen);
                newSeen.add(sub);
                dfs[0].accept(index+len, newSeen);
            }
        }
    };
    dfs[0].accept(0, new java.util.HashSet<>());
    return best[0];
}

